def transform(grid):
    out = [row[:] for row in grid]
    # For each horizontal run of the non-background color that starts at the left edge,
    # color the remaining right-hand background cells with marker color 1.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    for r, row in enumerate(grid):
        if row[0] != bg:
            c = len(row) - 1
            while c >= 0 and row[c] == bg:
                out[r][c] = 1
                c -= 1
    return out
